#include "sound.h"
#include "main.h"

/* TIM1 handle generated by CubeMX (TIM1, Channel 1 = PWM Generation CH1, pin PE9 = Zio D6) */
extern TIM_HandleTypeDef htim1;

/* The timer counts at 1 MHz (1 count = 1 microsecond).
   Period in counts = 1,000,000 / frequency, so ARR = (1,000,000 / frequency) - 1. */
#define TICK_HZ 1000000UL

/* One note in a tune = a pitch and how long to hold it. */
typedef struct {
    uint16_t freq_hz;   /* pitch in Hz (higher number = higher pitch). 0 = rest (silence) */
    uint16_t dur_ms;    /* how long to hold this note, in milliseconds. 0 = end of the tune */
} Note;

/* ---------------------------------------------------------------------------
   TUNES
   Each tune is an array of notes played one after another, left to right.
   The last entry {0, 0} is the end marker, so the player knows when to stop.
   Edit the numbers to change a sound.
   --------------------------------------------------------------------------- */

/* HAPPY: a quick rising run, like a little "ta-da" (C major arpeggio).
   Rising pitch sounds cheerful. */
static const Note snd_happy[] = {
    {523, 120},    /* C5  - 523 Hz, short note (120 ms)               */
    {659, 120},    /* E5  - 659 Hz, a step higher                     */
    {784, 120},    /* G5  - 784 Hz, higher again                      */
    {1047, 250},   /* C6  - 1047 Hz, top note held longer (250 ms)    */
    {0, 0}         /* end of tune                                     */
};

/* HUNGRY: three identical beeps with short gaps, like a repeating "feed me" alert.
   Same pitch every time, in the middle range, so it sounds like a nagging reminder. */
static const Note snd_hungry[] = {
    {440, 200},    /* A4  - 440 Hz beep (200 ms)                      */
    {0, 100},      /* rest - silence for 100 ms (gap between beeps)   */
    {440, 200},    /* A4  - second beep                               */
    {0, 100},      /* rest - silence for 100 ms                       */
    {440, 200},    /* A4  - third beep                                */
    {0, 0}         /* end of tune                                     */
};

/* DYING: a slow falling run that ends on a long low note, like a sad "wah-wah".
   Falling pitch and a long final note sound like the pet is fading out. */
static const Note snd_dying[] = {
    {392, 250},    /* G4  - 392 Hz (250 ms)                           */
    {330, 250},    /* E4  - 330 Hz, a step lower                      */
    {262, 300},    /* C4  - 262 Hz, lower again, held a bit longer    */
    {196, 700},    /* G3  - 196 Hz, lowest note, held long (700 ms)   */
    {0, 0}         /* end of tune                                     */
};

/* CRITICAL LOW: one short, high-pitched beep to flag a low pet stat. */
static const Note snd_critical_low[] = {
    {880, 180},    /* A5 alert beep                                   */
    {0, 0}          /* end of tune                                     */
};

/* Playback state: which tune is playing, which note we are on, and when that note began. */
static const Note *cur_seq = 0;    /* pointer to the tune being played (0 = nothing playing) */
static uint8_t  cur_idx = 0;       /* index of the current note within the tune              */
static uint32_t note_start_ms = 0; /* HAL_GetTick() value when the current note started      */

/* Returns the clock speed feeding TIM1. TIM1 is on the APB2 bus.
   If the APB2 prescaler is not 1, the timer clock is doubled. */
static uint32_t timer_clock_hz(void)
{
    uint32_t pclk2 = HAL_RCC_GetPCLK2Freq();
    return (RCC->CFGR & RCC_CFGR_PPRE2_2) ? (pclk2 * 2U) : pclk2;
}

// Sets the speaker to a given pitch. freq_hz = 0 turns the sound off. 
static void set_tone(uint16_t freq_hz)
{
    if (freq_hz == 0) {
        __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, 0);   // duty cycle 0% = silence 
        return;
    }
    uint32_t arr = (TICK_HZ / freq_hz) - 1U;                /* period for this pitch */
    __HAL_TIM_SET_AUTORELOAD(&htim1, arr);                  /* set the PWM period    */
    __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, (arr + 1U) / 2U);  /* 50% duty cycle = square wave */
    __HAL_TIM_SET_COUNTER(&htim1, 0);                       /* restart the count cleanly */
}

/* Call once after the timer is initialized. Starts PWM output, silent. */
void Sound_Init(void)
{
    /* Prescaler divides timer clock down to 1 MHz */
    __HAL_TIM_SET_PRESCALER(
        &htim1,
        (timer_clock_hz() / TICK_HZ) - 1U
    );

    /* Force the new prescaler value to take effect */
    HAL_TIM_GenerateEvent(
        &htim1,
        TIM_EVENTSOURCE_UPDATE
    );

    /* Start silent */
    __HAL_TIM_SET_COMPARE(
        &htim1,
        TIM_CHANNEL_1,
        0
    );

    /* Enable PWM output on PE9 */
    HAL_TIM_PWM_Start(
        &htim1,
        TIM_CHANNEL_1
    );
}

// Starts a tune from its first note. Returns right away (does not wait). 
void Sound_Play(SoundId id)
{
    switch (id) {
    case SOUND_HAPPY:  cur_seq = snd_happy;  break;
    case SOUND_HUNGRY: cur_seq = snd_hungry; break;
    case SOUND_DYING:  cur_seq = snd_dying;  break;
    case SOUND_CRITICAL_LOW: cur_seq = snd_critical_low; break;
    default:           Sound_Stop();         return;
    }
    cur_idx = 0;                          /* start at the first note */
    note_start_ms = HAL_GetTick();        /* remember when it began  */
    set_tone(cur_seq[0].freq_hz);         /* play the first note     */
}

// Stops any tune and silences the speaker. 
void Sound_Stop(void)
{
    cur_seq = 0;
    set_tone(0);
}

/* Call every pass of the main loop. When the current note has lasted long enough,
   moves on to the next one. Uses time checks only, so it never blocks the program. */
void Sound_Update(void)
{
    if (cur_seq == 0) return;             // nothing playing 

    if ((HAL_GetTick() - note_start_ms) >= cur_seq[cur_idx].dur_ms) {
        cur_idx++;                        // move to the next note 
        if (cur_seq[cur_idx].dur_ms == 0) {   // hit the {0, 0} end marker 
            Sound_Stop();
            return;
        }
        note_start_ms = HAL_GetTick();
        set_tone(cur_seq[cur_idx].freq_hz);
    }
}

// Returns 1 if a tune is currently playing, 0 if not. 
uint8_t Sound_IsPlaying(void)
{
    return (cur_seq != 0);
}